import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Слэш-команды","description":"","frontmatter":{},"headers":[],"relativePath":"ru/guides/slash-commands.md","filePath":"ru/guides/slash-commands.md","lastUpdated":1792323081000}'),c={name:"ru/guides/slash-commands.md"};function s(l,t,r,i,n,h){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="слэш-команды" tabindex="-1">Слэш-команды <a class="header-anchor" href="#слэш-команды" aria-label="Permalink to &quot;Слэш-команды&quot;">​</a></h1><p>Bot в Memoh поддерживают <strong>слэш-команды</strong>, которые перехватываются до запуска LLM. Они предназначены для быстрых задач просмотра и управления: посмотреть настройки, переключить провайдера, проверить статус сессии или создать свежую сессию.</p><p>Слэш-команды работают в адаптерах каналов и во встроенном чате приложения. Сам разбор команды не расходует токены модели.</p><hr><h2 id="устроиство-команд" tabindex="-1">Устройство команд <a class="header-anchor" href="#устроиство-команд" aria-label="Permalink to &quot;Устройство команд&quot;">​</a></h2><p>Большинство команд следует схеме «ресурс — действие»:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/resource [action] [arguments...]</span></span></code></pre></div><p>Примеры:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule list</span></span>\n<span class="line"><span>/model current</span></span>\n<span class="line"><span>/schedule create morning-news &quot;0 9 * * *&quot; &quot;Send a daily summary&quot;</span></span></code></pre></div><p>Ключевые идеи:</p><ul><li><strong>resource</strong> — группа команд, например <code>schedule</code>, <code>model</code> или <code>status</code>.</li><li><strong>action</strong> — конкретная операция, например <code>list</code>, <code>get</code>, <code>set</code> или <code>latest</code>.</li><li><strong>arguments</strong> — позиционные значения после действия. Значения с пробелами заключайте в кавычки.</li><li>У некоторых групп есть <strong>действие по умолчанию</strong>: <code>/settings</code> эквивалентна <code>/settings get</code>, а <code>/status</code> — <code>/status show</code>.</li></ul><p>Две команды являются <strong>командами верхнего уровня</strong>, а не группами ресурсов:</p><ul><li><code>/new</code> — создать новую сессию для текущего маршрута диалога</li><li><code>/stop</code> — прервать текущую генерацию в текущем диалоге</li></ul><hr><h2 id="активация-навыков-и-быстрые-деиствия" tabindex="-1">Активация навыков и быстрые действия <a class="header-anchor" href="#активация-навыков-и-быстрые-деиствия" aria-label="Permalink to &quot;Активация навыков и быстрые действия&quot;">​</a></h2><p>Помимо фиксированных команд, слэш-система может по запросу активировать <a href="./skills.html">навыки</a> Bot:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/&lt;skill-name&gt; [необязательный промпт]</span></span></code></pre></div><ul><li>В <strong>поле ввода приложения</strong> ввод <code>/</code> открывает панель с быстрыми действиями (<strong>Quick actions</strong>: <code>/help</code>, <code>/skill list</code>, <code>/new</code>, <code>/compact</code>, <code>/model</code>) и навыками Bot. Выбранный навык прикрепляется как удаляемый чип; можно и напрямую набрать форму, показанную выше.</li><li>В <strong>IM-каналах</strong> работает та же форма <code>/&lt;skill-name&gt;</code>, а <code>/skill list</code> выводит доступные навыки нажимаемыми кнопками.</li><li>Содержимое активированного навыка подставляется <strong>только в текущий ход</strong> — оно не сохраняется в истории, заголовках сессий или памяти.</li></ul><p>Имена навыков разрешаются <strong>на сервере</strong> по текущему действующему каталогу навыков Bot при каждой отправке. Ввод в форме слэш-команды, не совпавший ни с одной известной командой или навыком, отклоняется с понятной ошибкой, а не передаётся модели; при этом обычный текст, просто начинающийся с <code>/</code> (пути, URL), по-прежнему уходит как обычное сообщение.</p><p>Два ограничения, о которых стоит знать:</p><ul><li>Сообщение активации навыка не может нести вложения (фиксированные команды с вложениями выполняются как обычно).</li><li>В групповых чатах слэш-сообщение, не адресованное Bot, молча игнорируется.</li></ul><h2 id="встроенная-справка" tabindex="-1">Встроенная справка <a class="header-anchor" href="#встроенная-справка" aria-label="Permalink to &quot;Встроенная справка&quot;">​</a></h2><p>В слэш-систему встроена многоуровневая справка:</p><table tabindex="0"><thead><tr><th>Команда</th><th>Значение</th></tr></thead><tbody><tr><td><code>/help</code></td><td>Показать список команд верхнего уровня</td></tr><tr><td><code>/help &lt;group&gt;</code></td><td>Показать действия внутри одной группы</td></tr><tr><td><code>/help &lt;group&gt; &lt;action&gt;</code></td><td>Показать подробное использование одного действия</td></tr></tbody></table><p>Примеры:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/help</span></span>\n<span class="line"><span>/help model</span></span>\n<span class="line"><span>/help model set</span></span></code></pre></div><p>Это самый быстрый способ узнать точный действующий набор команд вашей текущей версии Memoh.</p><hr><h2 id="правила-разбора" tabindex="-1">Правила разбора <a class="header-anchor" href="#правила-разбора" aria-label="Permalink to &quot;Правила разбора&quot;">​</a></h2><p>Слэш-команды поддерживают несколько удобных форм:</p><ul><li><strong>Команды с упоминанием</strong> работают в групповых чатах, например <code>@BotName /help</code>.</li><li>Принимаются <strong>суффиксы Telegram-ботов</strong>, например <code>/help@MemohBot</code>.</li><li>Строки в кавычках сохраняются как один аргумент, например:</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule create morning-news &quot;0 9 * * *&quot; &quot;Send today&#39;s top stories&quot;</span></span></code></pre></div><p>Если текст не разрешается в известную команду, Memoh считает его обычным сообщением чата, а не слэш-командой.</p><hr><h2 id="права" tabindex="-1">Права <a class="header-anchor" href="#права" aria-label="Permalink to &quot;Права&quot;">​</a></h2><p>Действия только для чтения доступны пользователям, которые уже могут общаться с Bot. Действия записи, такие как <code>set</code>, <code>create</code>, <code>update</code>, <code>delete</code>, <code>enable</code> и <code>disable</code>, — <strong>только для владельца</strong>.</p><p>В выводе <code>/help</code> действия, доступные только владельцу, помечены <code>[owner]</code>.</p><hr><h2 id="краткии-справочник" tabindex="-1">Краткий справочник <a class="header-anchor" href="#краткии-справочник" aria-label="Permalink to &quot;Краткий справочник&quot;">​</a></h2><h3 id="команды-верхнего-уровня" tabindex="-1">Команды верхнего уровня <a class="header-anchor" href="#команды-верхнего-уровня" aria-label="Permalink to &quot;Команды верхнего уровня&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Команда</th><th>Описание</th></tr></thead><tbody><tr><td><code>/help</code></td><td>Показать справку по слэш-командам</td></tr><tr><td><code>/new [chat|discuss]</code></td><td>Создать новую сессию для текущего маршрута</td></tr><tr><td><code>/stop</code></td><td>Остановить текущую генерацию</td></tr></tbody></table><h3 id="группы-ресурсов" tabindex="-1">Группы ресурсов <a class="header-anchor" href="#группы-ресурсов" aria-label="Permalink to &quot;Группы ресурсов&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Группа</th><th>Описание</th><th>Действие по умолчанию</th></tr></thead><tbody><tr><td><code>/schedule</code></td><td>Управление задачами по расписанию</td><td>Нет</td></tr><tr><td><code>/mcp</code></td><td>Просмотр подключений MCP</td><td>Нет</td></tr><tr><td><code>/settings</code></td><td>Просмотр и изменение настроек Bot</td><td><code>get</code></td></tr><tr><td><code>/model</code></td><td>Просмотр и переключение моделей Bot</td><td>Нет</td></tr><tr><td><code>/memory</code></td><td>Просмотр и переключение провайдеров памяти</td><td>Нет</td></tr><tr><td><code>/search</code></td><td>Просмотр и переключение провайдеров поиска</td><td>Нет</td></tr><tr><td><code>/usage</code></td><td>Просмотр расхода токенов</td><td><code>summary</code></td></tr><tr><td><code>/email</code></td><td>Просмотр почтовых провайдеров, привязок и исходящих</td><td>Нет</td></tr><tr><td><code>/skill</code></td><td>Просмотр загруженных навыков Bot</td><td><code>list</code></td></tr><tr><td><code>/fs</code></td><td>Просмотр файлов в рабочем пространстве Bot</td><td>Нет</td></tr><tr><td><code>/status</code></td><td>Просмотр статуса сообщений/контекста/кэша сессии</td><td><code>show</code></td></tr><tr><td><code>/access</code></td><td>Просмотр контекста идентичности, роли и ACL</td><td><code>show</code></td></tr><tr><td><code>/compact</code></td><td>Немедленное сжатие контекста сессии</td><td><code>run</code></td></tr><tr><td><code>/context</code></td><td>Показ занятости контекстного окна текущей сессии</td><td><code>show</code></td></tr><tr><td><code>/reasoning</code> (псевдонимы <code>/reason</code>, <code>/effort</code>, <code>/think</code>)</td><td>Просмотр или установка уровня рассуждения для этой сессии</td><td><code>show</code></td></tr><tr><td><code>/language</code></td><td>Просмотр или установка языка интерфейса команд (<code>auto</code>, <code>en</code>, <code>zh</code>, <code>ja</code>)</td><td><code>show</code></td></tr><tr><td><code>/link &lt;code&gt;</code></td><td>Привязка аккаунта этого канала к вашему пользователю Memoh по коду, сгенерированному в приложении</td><td><code>consume</code></td></tr></tbody></table><hr><h2 id="команды-сессии" tabindex="-1">Команды сессий <a class="header-anchor" href="#команды-сессии" aria-label="Permalink to &quot;Команды сессий&quot;">​</a></h2><h3 id="new" tabindex="-1"><code>/new</code> <a class="header-anchor" href="#new" aria-label="Permalink to &quot;`/new`&quot;">​</a></h3><p>Создаёт свежую сессию для текущего маршрута диалога. Это самый быстрый способ сбросить контекст разговора без удаления старой истории.</p><p>Поддерживаемые формы:</p><ul><li><code>/new</code> — использовать тип сессии по умолчанию для текущего контекста</li><li><code>/new chat</code> — принудительно создать обычную сессию chat</li><li><code>/new discuss</code> — принудительно создать сессию discuss</li></ul><p>Поведение по умолчанию:</p><ul><li><strong>встроенный чат приложения</strong> по умолчанию использует <code>chat</code></li><li><strong>личные сообщения</strong> по умолчанию используют <code>chat</code></li><li><strong>групповые диалоги на адаптерах каналов</strong> по умолчанию используют <code>discuss</code></li></ul><p><code>/new discuss</code> не поддерживается во встроенном чат-канале приложения. Если нужны явные сессии discuss, используйте адаптер канала, например Telegram или Discord.</p><p>О том, чем различаются <code>chat</code> и <code>discuss</code>, см. <a href="./sessions.html">Сессии</a>.</p><h3 id="stop" tabindex="-1"><code>/stop</code> <a class="header-anchor" href="#stop" aria-label="Permalink to &quot;`/stop`&quot;">​</a></h3><p>Останавливает текущую выполняющуюся генерацию в текущем диалоге. Это полезно, когда:</p><ul><li>Bot ещё выводит ответ, а вы уже получили нужное</li><li>цикл инструментов затянулся</li><li>вы хотите прервать текущий ход, прежде чем отправить следующее сообщение</li></ul><hr><h2 id="команды-статуса-и-диагностики" tabindex="-1">Команды статуса и диагностики <a class="header-anchor" href="#команды-статуса-и-диагностики" aria-label="Permalink to &quot;Команды статуса и диагностики&quot;">​</a></h2><h3 id="status" tabindex="-1"><code>/status</code> <a class="header-anchor" href="#status" aria-label="Permalink to &quot;`/status`&quot;">​</a></h3><p>Показывает статистику текущего диалога на уровне сессии:</p><ul><li>число сообщений</li><li>текущую занятость контекста</li><li>долю попаданий в кэш</li><li>токены чтения/записи кэша</li><li>использованные в сессии навыки</li></ul><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th></tr></thead><tbody><tr><td><code>show</code></td><td><code>/status</code> или <code>/status show</code></td></tr><tr><td><code>latest</code></td><td><code>/status latest</code></td></tr></tbody></table><p>Используйте <code>show</code> для активного сейчас маршрута диалога. Используйте <code>latest</code>, когда нужна самая свежая сессия Bot, даже если на текущем маршруте нет активной сессии.</p><h3 id="access" tabindex="-1"><code>/access</code> <a class="header-anchor" href="#access" aria-label="Permalink to &quot;`/access`&quot;">​</a></h3><p>Показывает текущую идентичность и контекст прав, которые Memoh использует для команды:</p><ul><li>идентичность канала</li><li>привязанного пользователя</li><li>роль для этого Bot</li><li>разрешены ли команды записи</li><li>область: канал / диалог / тред</li><li>вычисленный результат ACL для чата</li></ul><p>Использование:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/access</span></span></code></pre></div><p>Эта команда полезна при отладке правил ACL и выяснении, почему команда записи была отклонена.</p><h3 id="usage" tabindex="-1"><code>/usage</code> <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;`/usage`&quot;">​</a></h3><p>Показывает расход токенов за последние 7 дней.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th></tr></thead><tbody><tr><td><code>summary</code></td><td><code>/usage</code> или <code>/usage summary</code></td></tr><tr><td><code>by-model</code></td><td><code>/usage by-model</code></td></tr></tbody></table><h3 id="email" tabindex="-1"><code>/email</code> <a class="header-anchor" href="#email" aria-label="Permalink to &quot;`/email`&quot;">​</a></h3><p>Показывает связанные с почтой данные конфигурации текущего Bot.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th></tr></thead><tbody><tr><td><code>providers</code></td><td><code>/email providers</code></td></tr><tr><td><code>bindings</code></td><td><code>/email bindings</code></td></tr><tr><td><code>outbox</code></td><td><code>/email outbox</code></td></tr></tbody></table><hr><h2 id="команды-конфигурации" tabindex="-1">Команды конфигурации <a class="header-anchor" href="#команды-конфигурации" aria-label="Permalink to &quot;Команды конфигурации&quot;">​</a></h2><h3 id="settings" tabindex="-1"><code>/settings</code> <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;`/settings`&quot;">​</a></h3><p>Показывает или изменяет основные настройки Bot.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th><th>Права</th></tr></thead><tbody><tr><td><code>get</code></td><td><code>/settings</code> или <code>/settings get</code></td><td>Все</td></tr><tr><td><code>update</code></td><td><code>/settings update [options]</code></td><td>Владелец</td></tr></tbody></table><p>Поддерживаемые опции <code>update</code>:</p><table tabindex="0"><thead><tr><th>Опция</th><th>Описание</th></tr></thead><tbody><tr><td><code>--language</code></td><td>Язык Bot, например <code>en</code> или <code>zh</code></td></tr><tr><td><code>--acl_default_effect</code></td><td><code>allow</code> или <code>deny</code></td></tr><tr><td><code>--reasoning_effort</code></td><td>Уровень усилий, например <code>low</code>, <code>medium</code>, <code>high</code>, <code>xhigh</code> — допустимые значения зависят от уровней рассуждения, объявленных выбранной моделью</td></tr><tr><td><code>--chat_model_id</code></td><td>UUID модели чата</td></tr></tbody></table><p>Пример:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/settings update --language en --reasoning_effort high</span></span></code></pre></div><h3 id="model" tabindex="-1"><code>/model</code> <a class="header-anchor" href="#model" aria-label="Permalink to &quot;`/model`&quot;">​</a></h3><p>Показывает или переключает модель чата Bot.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th><th>Права</th></tr></thead><tbody><tr><td><code>list [provider_name]</code></td><td><code>/model list</code></td><td>Все</td></tr><tr><td><code>current</code></td><td><code>/model current</code></td><td>Все</td></tr><tr><td><code>set</code></td><td><code>/model set &lt;model_id&gt;</code> или <code>/model set &lt;provider_name&gt; &lt;model_name&gt;</code></td><td>Владелец</td></tr></tbody></table><p>Примеры:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/model list</span></span>\n<span class="line"><span>/model list OpenAI</span></span>\n<span class="line"><span>/model current</span></span>\n<span class="line"><span>/model set gpt-4o</span></span>\n<span class="line"><span>/model set OpenAI gpt-4o</span></span></code></pre></div><h3 id="memory" tabindex="-1"><code>/memory</code> <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;`/memory`&quot;">​</a></h3><p>Показывает или переключает активного провайдера памяти.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th><th>Права</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/memory list</code></td><td>Все</td></tr><tr><td><code>current</code></td><td><code>/memory current</code></td><td>Все</td></tr><tr><td><code>set</code></td><td><code>/memory set &lt;name&gt;</code></td><td>Владелец</td></tr></tbody></table><h3 id="search" tabindex="-1"><code>/search</code> <a class="header-anchor" href="#search" aria-label="Permalink to &quot;`/search`&quot;">​</a></h3><p>Показывает или переключает активного провайдера поиска.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th><th>Права</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/search list</code></td><td>Все</td></tr><tr><td><code>current</code></td><td><code>/search current</code></td><td>Все</td></tr><tr><td><code>set</code></td><td><code>/search set &lt;name&gt;</code></td><td>Владелец</td></tr></tbody></table><h3 id="mcp" tabindex="-1"><code>/mcp</code> <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;`/mcp`&quot;">​</a></h3><p>Показывает или удаляет подключения MCP, настроенные для Bot.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th><th>Права</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/mcp list</code></td><td>Все</td></tr><tr><td><code>get</code></td><td><code>/mcp get &lt;name&gt;</code></td><td>Все</td></tr><tr><td><code>delete</code></td><td><code>/mcp delete &lt;name&gt;</code></td><td>Владелец</td></tr></tbody></table><hr><h2 id="команды-автоматизации-и-фаиловои-системы" tabindex="-1">Команды автоматизации и файловой системы <a class="header-anchor" href="#команды-автоматизации-и-фаиловои-системы" aria-label="Permalink to &quot;Команды автоматизации и файловой системы&quot;">​</a></h2><h3 id="schedule" tabindex="-1"><code>/schedule</code> <a class="header-anchor" href="#schedule" aria-label="Permalink to &quot;`/schedule`&quot;">​</a></h3><p>Управляет задачами по расписанию для Bot.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th><th>Права</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/schedule list</code></td><td>Все</td></tr><tr><td><code>get</code></td><td><code>/schedule get &lt;name&gt;</code></td><td>Все</td></tr><tr><td><code>create</code></td><td><code>/schedule create &lt;name&gt; &lt;pattern&gt; &lt;command&gt;</code></td><td>Владелец</td></tr><tr><td><code>update</code></td><td><code>/schedule update &lt;name&gt; [--pattern P] [--command C]</code></td><td>Владелец</td></tr><tr><td><code>delete</code></td><td><code>/schedule delete &lt;name&gt;</code></td><td>Владелец</td></tr><tr><td><code>enable</code></td><td><code>/schedule enable &lt;name&gt;</code></td><td>Владелец</td></tr><tr><td><code>disable</code></td><td><code>/schedule disable &lt;name&gt;</code></td><td>Владелец</td></tr></tbody></table><p>Примеры:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/schedule list</span></span>\n<span class="line"><span>/schedule create morning-news &quot;0 9 * * *&quot; &quot;Summarize today&#39;s top tech news&quot;</span></span>\n<span class="line"><span>/schedule disable morning-news</span></span></code></pre></div><h3 id="skill" tabindex="-1"><code>/skill</code> <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;`/skill`&quot;">​</a></h3><p>Выводит доступные сейчас навыки Bot. Показываются только навыки, <strong>пригодные к использованию во время работы</strong>, — отключённые или перекрытые источники опускаются.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/skill</code> или <code>/skill list</code></td></tr></tbody></table><p>Чтобы активировать навык на один ход, используйте <code>/&lt;skill-name&gt; [промпт]</code> — см. <a href="#активация-навыков-и-быстрые-деиствия">Активацию навыков и быстрые действия</a>.</p><h3 id="fs" tabindex="-1"><code>/fs</code> <a class="header-anchor" href="#fs" aria-label="Permalink to &quot;`/fs`&quot;">​</a></h3><p>Просматривает файловую систему рабочего пространства Bot.</p><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th></tr></thead><tbody><tr><td><code>list</code></td><td><code>/fs list [path]</code></td></tr><tr><td><code>read</code></td><td><code>/fs read &lt;path&gt;</code></td></tr></tbody></table><p>Примеры:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/fs list /</span></span>\n<span class="line"><span>/fs list /home</span></span>\n<span class="line"><span>/fs read /home/bot/IDENTITY.md</span></span></code></pre></div><p>Вывод чтения усекается, если файл очень большой.</p><hr><h2 id="команда-сжатия-контекста" tabindex="-1">Команда сжатия контекста <a class="header-anchor" href="#команда-сжатия-контекста" aria-label="Permalink to &quot;Команда сжатия контекста&quot;">​</a></h2><h3 id="compact" tabindex="-1"><code>/compact</code> <a class="header-anchor" href="#compact" aria-label="Permalink to &quot;`/compact`&quot;">​</a></h3><p>Немедленно запускает <strong>сжатие контекста сессии</strong> для текущей сессии. Это не то же самое, что сжатие памяти:</p><ul><li><strong>сжатие контекста</strong> уменьшает объём активного промпта и истории одной сессии</li><li><strong>сжатие памяти</strong> переписывает записи долговременной памяти у провайдера памяти</li></ul><p>Действия:</p><table tabindex="0"><thead><tr><th>Действие</th><th>Использование</th></tr></thead><tbody><tr><td><code>run</code></td><td><code>/compact</code> или <code>/compact run</code></td></tr></tbody></table><p>Используйте эту команду, когда текущий разговор разросся и вы хотите, чтобы Memoh резюмировал старые ходы, прежде чем продолжать. См. <a href="./compaction.html">Сжатие контекста</a>.</p>',134)])])}const b=e(c,[["render",s]]);export{u as __pageData,b as default};
